<?php

namespace App\Helpers;

use App\Models\ContentType;
use App\Models\Page;

class MenuHelper
{
    public static function getMainNavItems()
    {
        
        $pages = Page::all();
        $arPages = [];
        foreach ($pages as $page) {
           $arPages[] = ['name' => $page->title, 'path' => route('pages.edit', ['tenant' => tenant('id'), 'page' => $page->id])];
        }
        return [
            [
                'icon' => 'chart',
                'name' => 'Estadisticas',
                'path' => route('v2.index', ['tenant' => tenant('id')])
            ],
            [
                'icon' => 'dashboard',
                'name' => 'Dinámicas',
                'path' => route('dynamics.index', ['tenant' => tenant('id')]),
                
            ],
            [
                'icon' => 'rss',
                'name' => 'Campañas',
                'path' => route('campaigns.index', ['tenant' => tenant('id')]),
            ],
            [
                'icon' => 'game',
                'name' => 'Juegos',
                'subItems' => [
                    ['name' => 'Aplazo Games', 'path' => route('aplazogames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Catch Games', 'path' => route('catchgames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Click Win', 'path' => route('clickwingames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Compartir', 'path' => route('sharegames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Flappy Bird', 'path' => route('flappygames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Memoramas', 'path' => route('memorygames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Penales', 'path' => route('penalgames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Rompecabezas', 'path' => route('puzzlegames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Smash Games', 'path' => route('smashgames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Trivias', 'path' => route('triviagames.index', ['tenant' => tenant('id')])],
                    ['name' => 'Votaciones', 'path' => route('votegames.index', ['tenant' => tenant('id')])],
                ],
            ],
            [
                'name' => 'Códigos de Premios',
                'icon' => 'ticket',
                'path' => route('awardcodes.index', ['tenant' => tenant('id')]),
            ],
            [
                'name' => 'Tickets',
                'icon' => 'document-upload',
                'subItems' => [
                    ['name' => 'Preguntas de Tickets', 'path' => route('ticketquestions.index', ['tenant' => tenant('id')])],
                    ['name' => 'Tickets Enviados', 'path' => route('tickets.index', ['tenant' => tenant('id')])],
                ],
            ],
            [
                'name' => 'Páginas',
                'icon' => 'pages',
                'path' => route('pages.index', ['tenant' => tenant('id')]),
                'subItems' => $arPages,
            ],
            [
                'name' => 'Recursos',
                'icon' => 'media',
                'path' => route('resources.index', ['tenant' => tenant('id')]),
            ],
        ];
    }

    public static function getOthersItems()
    {
        return [
            [
                'icon' => 'setting',
                'name' => 'Options',
                'path' => route('v2.options', ['tenant' => tenant('id')])
            ],
            // [
            //     'icon' => 'code',
            //     'name' => 'Integraciones',
            //     'path' => route('v2.integrations', ['tenant' => tenant('id')])
            // ],
        ];
    }

    public static function getMenuGroups()
    {
        return [
            [
                'title' => 'Menu',
                'items' => self::getMainNavItems()
            ],
            [
                'title' => 'Others',
                'items' => self::getOthersItems()
            ]
        ];
    }

    public static function isActive($path)
    {
        return request()->is(ltrim($path, '/'));
    }

